import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  // Create plane geometry with 512x320 aspect ratio (1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Load texture
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create material
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement
  const pos = config.scenePosition || { x: 0, y: 0, z: 0 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scale = config.sceneScale || { x: 1, y: 1, z: 1 };

  mesh.position.set(pos.x, pos.y, pos.z);
  mesh.rotation.set(rot.x, rot.y, rot.z);
  mesh.scale.set(scale.x, scale.y, scale.z);

  // Create container
  const container = new THREE.Object3D();
  container.add(mesh);

  // Setup cleanup
  container.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  container.userData.handlers = {};

  return container;
}
